using System.Net;using Microsoft.AspNetCore.Mvc.Testing;using Xunit;namespace CRM.UnitTests;public sealed class Sprint29InsightApiTests{[Fact]public async Task Detail_IsGetOnly(){using var f=new WebApplicationFactory<Program>();using var c=f.CreateClient();Assert.Equal(HttpStatusCode.OK,(await c.GetAsync("/api/crm/foundation/insights/accounts-contacts")).StatusCode);using var q=new HttpRequestMessage(HttpMethod.Post,"/api/crm/foundation/insights/accounts-contacts");var r=await c.SendAsync(q);Assert.True(r.StatusCode is HttpStatusCode.NotFound or HttpStatusCode.MethodNotAllowed);Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync("/api/crm/insights/accounts-contacts")).StatusCode);}}